def transform(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; stack.append((ny,nx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                if y1-y0>=2 and x1-x0>=2:
                    interior=[(y,x) for y in range(y0+1,y1) for x in range(x0+1,x1) if g[y][x]==0]
                    if interior:
                        fill=2 if len(interior)%2==0 else 7
                        for y,x in interior: out[y][x]=fill
    return out

