def bbox(cells):
    """The (top, left, height, width) bounding box of a list of (y, x) cells."""
    ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
    return min(ys), min(xs), max(ys) - min(ys) + 1, max(xs) - min(xs) + 1

def is_ring(cells):
    """True if the cells exactly form the border ring of their bounding box."""
    top, left, h, w = bbox(cells)
    return h >= 3 and w >= 3 and len(cells) == 2 * (h + w) - 4

def fill_rings(grid, fill_fn):
    """Fill the interior of every rectangular ring component with fill_fn(h, w) of its inner size."""
    out = [row[:] for row in grid]
    for c, cells in components(grid):
        if is_ring(cells):
            top, left, h, w = bbox(cells)
            fill = fill_fn(h - 2, w - 2)
            for y in range(top + 1, top + h - 1):
                for x in range(left + 1, left + w - 1):
                    out[y][x] = fill
    return out
